/* @autogenerated */
package net.civeira.phylax.feature.observe.ingest;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Events per minute that each source can store (observed-source rate-limit): a token bucket per
 * source, refilled continuously, so short bursts pass and a sustained flood is cut. The excess is
 * dropped and counted (dropped-count). The application itself is not limited (its min-level already
 * chooses what it keeps). Only in memory, without locks other than the one of the bucket.
 */
public class RateLimiter {

  /** Bucket of a source: tokens and last refill. */
  private static final class Bucket {
    double tokens;
    long refilled;
    int limit;
  }

  private final Map<String, Bucket> buckets = new ConcurrentHashMap<>();

  /**
   * @param perMinute limit of the source; 0 or less: no limit
   * @return true if the event can be stored
   */
  public boolean allow(final String source, final int perMinute, final long nowMillis) {
    if (perMinute <= 0) {
      return true;
    }
    Bucket bucket = buckets.computeIfAbsent(source, key -> {
      Bucket created = new Bucket();
      created.tokens = perMinute;
      created.refilled = nowMillis;
      created.limit = perMinute;
      return created;
    });
    synchronized (bucket) {
      if (bucket.limit != perMinute) {
        bucket.limit = perMinute;
        bucket.tokens = Math.min(bucket.tokens, perMinute);
      }
      double refill = (nowMillis - bucket.refilled) * perMinute / 60_000.0;
      bucket.tokens = Math.min(perMinute, bucket.tokens + refill);
      bucket.refilled = nowMillis;
      if (bucket.tokens >= 1) {
        bucket.tokens -= 1;
        return true;
      }
      return false;
    }
  }
}
